@startuml

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + date : date
}

class Runner {
  + horseName : string
  + runnerId : int
}

class Jockey {
  + name : string
}

class Bet {
  + amount : float
  + odds : float
}

Bettor "1" -- "0..*" Bet
Race "1" -- "1..*" Runner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner
Race "0..1" -- "1" Runner : winner

@enduml

